package com.zineb.chat.client.app;
import com.zineb.chat.client.controller.ClientController; import com.zineb.chat.client.view.ClientView; import javafx.application.Application; import javafx.scene.Scene; import javafx.stage.Stage; import java.util.*;
public final class TCPClientApp extends Application {private ClientController controller;private String host="localhost";private int port=3000;public void init(){List<String>a=getParameters().getRaw();if(a.size()>=2){host=a.get(0);try{port=Integer.parseInt(a.get(1));}catch(NumberFormatException ignored){}}}public void start(Stage stage){ClientView view=new ClientView();controller=new ClientController(host,port,view);if(getParameters().getRaw().size()<2)view.append("Usage: java TCPClient <ServerIPAddress> <PortNumber> - using localhost:3000 for this run.");Scene scene=new Scene(view.root(),760,560);scene.getStylesheets().add(Objects.requireNonNull(getClass().getResource("/client.css")).toExternalForm());stage.setTitle("TCPClient - Zineb Maimmadi");stage.setScene(scene);stage.show();}public void stop(){if(controller!=null)controller.shutdown();}public static void main(String[]a){launch(a);}}
